using EduManageLms.Api.Domain; using MongoDB.Bson; using MongoDB.Driver;
namespace EduManageLms.Api.Infrastructure;
public sealed class DataSeeder(MongoContext db,ILogger<DataSeeder> log){public async Task SeedAsync(CancellationToken ct=default){if(await db.Users.EstimatedDocumentCountAsync(cancellationToken:ct)>0)return;var facultyId=ObjectId.GenerateNewId().ToString();var faculty=new FacultySnapshot{FacultyId=facultyId,FacultyCode="CNTT",FacultyName="Công nghệ thông tin"};var courseDefs=new[]{("NOSQL01","Cơ sở dữ liệu NoSQL",3),("WEBAPI","Phát triển Web API",3),("IOT101","Internet vạn vật",3),("SE101","Công nghệ phần mềm",3),("AI101","Nhập môn trí tuệ nhân tạo",3)};var scale=new List<GradeScaleItem>{new(){Min=8.5,Max=10,Letter="A",GradePoint=4},new(){Min=8,Max=8.49,Letter="B+",GradePoint=3.5},new(){Min=7,Max=7.99,Letter="B",GradePoint=3},new(){Min=6.5,Max=6.99,Letter="C+",GradePoint=2.5},new(){Min=5.5,Max=6.49,Letter="C",GradePoint=2},new(){Min=5,Max=5.49,Letter="D+",GradePoint=1.5},new(){Min=4,Max=4.99,Letter="D",GradePoint=1},new(){Min=0,Max=3.99,Letter="F",GradePoint=0}};var scheme=new GradingSchemeVersion{Version=1,AcademicYear="2025-2026",Components=[new(){ComponentId="CC",Name="Chuyên cần",Type="Attendance",Weight=10,MaxScore=10,CloMappings=[new(){CloCode="CLO1",MappingWeight=100}]},new(){ComponentId="BT",Name="Bài tập",Type="Assignment",Weight=20,MaxScore=10,CloMappings=[new(){CloCode="CLO1",MappingWeight=40},new(){CloCode="CLO2",MappingWeight=60}]},new(){ComponentId="GK",Name="Giữa kỳ",Type="Midterm",Weight=30,MaxScore=10,CloMappings=[new(){CloCode="CLO2",MappingWeight=100}]},new(){ComponentId="CK",Name="Cuối kỳ",Type="Final",Weight=40,MaxScore=10,IsRequired=true,MinimumScore=3,CloMappings=[new(){CloCode="CLO2",MappingWeight=40},new(){CloCode="CLO3",MappingWeight=60}]}]};var courses=courseDefs.Select((c,i)=>new Course{CourseCode=c.Item1,CourseName=c.Item2,Credits=c.Item3,Faculty=faculty,Description="Môn học thuộc chương trình Công nghệ thông tin",Clos=[new(){CloCode="CLO1",Name="Kiến thức nền tảng",Description="Trình bày được kiến thức cốt lõi",Threshold=50,Weight=30},new(){CloCode="CLO2",Name="Kỹ năng áp dụng",Description="Áp dụng kiến thức giải quyết bài toán",Threshold=50,Weight=40},new(){CloCode="CLO3",Name="Phân tích và đánh giá",Description="Phân tích, đánh giá giải pháp",Threshold=50,Weight=30}],GradingSchemes=[scheme],GradeScale=scale}).ToList();await db.Courses.InsertManyAsync(courses,cancellationToken:ct);var lecturer=new Lecturer{LecturerCode="GV001",FullName="Trần Văn Bình",Email="gv001@lms.edu.vn",Faculty=faculty,Department="Hệ thống thông tin",Specializations=["MongoDB","NoSQL"]};var lecturers=Enumerable.Range(1,10).Select(i=>i==1?lecturer:new Lecturer{LecturerCode=$"GV{i:000}",FullName=$"Giảng viên {i:00}",Email=$"gv{i:000}@lms.edu.vn",Faculty=faculty,Department=i%2==0?"Khoa học máy tính":"Hệ thống thông tin"}).ToList();await db.Lecturers.InsertManyAsync(lecturers,cancellationToken:ct);var yearId=ObjectId.GenerateNewId().ToString();var semesterId=ObjectId.GenerateNewId().ToString();var sections=courses.Select((c,i)=>new ClassSection{ClassSectionCode=$"{c.CourseCode}-01",CourseId=c.Id,CourseCode=c.CourseCode,CourseName=c.CourseName,AcademicYearId=yearId,AcademicYearName="2025-2026",SemesterId=semesterId,SemesterCode="HK1",SemesterName="Học kỳ 1",LecturerId=lecturers[i%lecturers.Count].Id,LecturerCode=lecturers[i%lecturers.Count].LecturerCode,LecturerName=lecturers[i%lecturers.Count].FullName,GradingSchemeSnapshot=scheme,GradeStatus=i==0?"InProgress":"Published",StartDate=DateTime.UtcNow.AddMonths(-2),EndDate=DateTime.UtcNow.AddMonths(2),Schedule=[new(){DayOfWeek=i%2==0?"Monday":"Wednesday",Room=$"A.{i+1}01"}]}).ToList();var students=new List<Student>();var rnd=new Random(2203);for(var i=1;i<=80;i++){var code=$"SV{i:000}";var st=new Student{StudentCode=code,FullName=$"Sinh viên {i:000}",Email=$"sv{i:000}@lms.edu.vn",Gender=i%2==0?"Nam":"Nữ",Faculty=faculty,Program=new(){ProgramId=ObjectId.GenerateNewId().ToString(),ProgramCode="CNTT2024",ProgramName="Công nghệ thông tin",RequiredCredits=130},Cohort="2024",AdministrativeClass=$"14DHTH{(i-1)/40+1:00}",Status="Studying"};var semester=new SemesterRecord{SemesterId=semesterId,SemesterCode="HK1",SemesterName="Học kỳ 1"};foreach(var (section,ci) in sections.Select((x,idx)=>(x,idx))){if(ci>1&&i%3!=ci%3)continue;var scoreBase=i%12==0?3.2:5.5+rnd.NextDouble()*4;var record=new StudentCourseRecord{CourseId=section.CourseId,CourseCode=section.CourseCode,CourseName=section.CourseName,Credits=courses[ci].Credits,ClassSectionId=section.Id,ClassSectionCode=section.ClassSectionCode,Lecturer=new(){LecturerId=section.LecturerId,LecturerCode=section.LecturerCode,FullName=section.LecturerName},GradingSchemeVersion=1,ScoreStatus=section.GradeStatus=="Published"?"Published":"InProgress",PublishedAt=section.GradeStatus=="Published"?DateTime.UtcNow.AddDays(-3):null,AttemptNumber=i%17==0?2:1,Scores=scheme.Components.Select((d,di)=>new ScoreComponent{ComponentId=d.ComponentId,ComponentName=d.Name,Type=d.Type,Weight=d.Weight,MaxScore=d.MaxScore,Score=(i%19==0&&di==3)?null:Math.Round(Math.Clamp(scoreBase+(rnd.NextDouble()-0.5)*2,0,10),1),Status=(i%19==0&&di==3)?"NotGraded":"Graded",IsRequired=d.IsRequired,MinimumScore=d.MinimumScore,CloMappings=d.CloMappings}).ToList()};semester.Courses.Add(record);section.Students.Add(new(){StudentId=st.Id,StudentCode=code,FullName=st.FullName});}st.AcademicRecords=[new(){AcademicYearId=yearId,AcademicYearName="2025-2026",Semesters=[semester]}];students.Add(st);}await db.Students.InsertManyAsync(students,cancellationToken:ct);await db.ClassSections.InsertManyAsync(sections,cancellationToken:ct);var users=new List<User>{new(){Username="admin",Email="admin@lms.edu.vn",FullName="Quản trị hệ thống",PasswordHash=BCrypt.Net.BCrypt.HashPassword("Lms@123456"),Role="Admin"}};users.AddRange(lecturers.Select(x=>new User{Username=x.LecturerCode.ToLowerInvariant(),Email=x.Email,FullName=x.FullName,PasswordHash=BCrypt.Net.BCrypt.HashPassword("Lms@123456"),Role="Lecturer",LecturerCode=x.LecturerCode}));users.AddRange(students.Select(x=>new User{Username=x.StudentCode.ToLowerInvariant(),Email=x.Email,FullName=x.FullName,PasswordHash=BCrypt.Net.BCrypt.HashPassword("Lms@123456"),Role="Student",StudentCode=x.StudentCode}));await db.Users.InsertManyAsync(users,cancellationToken:ct);await db.Notifications.InsertManyAsync(Enumerable.Range(1,20).Select(i=>new Notification{Title=$"Thông báo học vụ số {i}",Content="Nội dung thông báo mẫu có quan hệ với hoạt động đào tạo.",Priority=i%5==0?"High":"Normal",AudienceType=i%2==0?"Student":"All",SenderId=users[0].Id}).ToList(),cancellationToken:ct);await db.AuditLogs.InsertManyAsync(Enumerable.Range(1,15).Select(i=>new AuditLog{UserId=users[0].Id,UserName=users[0].FullName,Role="Admin",Action=i%2==0?"Create":"Update",Entity=i%3==0?"Course":"Student",IpAddress="127.0.0.1",UserAgent="Seed"}).ToList(),cancellationToken:ct);log.LogInformation("Seeded {Students} students, {Lecturers} lecturers and {Courses} courses",students.Count,lecturers.Count,courses.Count);}}
